test("expands approved filename tokens", () => {
  assert.equal(
    buildFilename("${documentName}-${date}-${time}", context, ".png", 1),
    "Product-Page-2026-09-02-142305.png",
  );
  assert.equal(buildFilename("${name}", context, ".jpg", 1), "Hero-image.jpg");
})

test("allocates deterministic collision names", () => {
  assert.equal(buildFilename("image", context, ".png", 1), "image.png");
  assert.equal(buildFilename("image", context, ".png", 2), "image-2.png");
  assert.equal(buildFilename("image-${counter}", context, ".png", 3), "image-3.png");
  const maximumStem = "x".repeat(96);
  const second = buildFilename(maximumStem, context, ".png", 2);
  assert.equal(second, `${"x".repeat(94)}-2.png`);
  assert.notEqual(second, buildFilename(maximumStem, context, ".png", 1));
  assert.match(buildFilename(`${maximumStem}-${"${counter}"}`, context, ".png", 2), /-2\.png$/);
})

test("sanitizes unsafe and Windows-reserved stems", () => {
  assert.equal(sanitizeStem("  hero: image?.png  "), "hero-image-.png");
  assert.equal(sanitizeStem("CON"), "image-CON");
  assert.equal(sanitizeStem(".."), "image");
  assert.equal(sanitizeStem("café 画面"), "café-画面");
})

test("normalizes a user-supplied image extension", () => {
  assert.equal(buildFilename("${name}", { ...context, requestedName: "hero.JPEG" }, ".png", 1), "hero.png");
})

test("rejects invalid templates and attempts", () => {
  assert.throws(() => buildFilename("", context, ".png", 1), FilenameError);
  assert.throws(() => buildFilename("folder/image", context, ".png", 1), FilenameError);
  assert.throws(() => buildFilename("${env}", context, ".png", 1), /Unsupported filename token/);
  assert.throws(() => buildFilename("${date", context, ".png", 1), /incomplete token/);
  assert.throws(() => buildFilename("image", context, ".png", 0), FilenameError);
})

test("validates explicit user names without silently accepting paths", () => {
  assert.equal(validateRequestedStem("hero-image"), undefined);
  assert.match(validateRequestedStem("../hero") ?? "", /path separators/);
  assert.match(validateRequestedStem("NUL") ?? "", /reserved/);
  assert.match(validateRequestedStem("image. ") ?? "", /dot or space/);
  assert.match(validateRequestedStem(" ") ?? "", /Enter/);
})

test("selects automatic formats without intercepting Markdown", () => {
  assert.equal(automaticFormatForLanguage("html", false), "html");
  assert.equal(automaticFormatForLanguage("scss", false), "css");
  assert.equal(automaticFormatForLanguage("mdx", false), "mdx");
  assert.equal(automaticFormatForLanguage("markdown", false), undefined);
  assert.equal(automaticFormatForLanguage("markdown", true), "markdown");
  assert.equal(automaticFormatForLanguage("typescript", false), undefined);
})

test("uses path-only output for explicit unknown-language paste", () => {
  assert.equal(explicitFormatForLanguage("typescript"), "path");
  assert.equal(explicitFormatForLanguage("unknown"), "path");
})

test("formats HTML, CSS, MDX, Markdown, and path references", () => {
  assert.equal(
    formatReference("html", "./assets/a&amp;b.png", "A \"quote\" & more"),
    '<img src="./assets/a&amp;amp;b.png" alt="A &quot;quote&quot; &amp; more">',
  );
  assert.equal(formatReference("css", './assets/a"b.png', ""), 'url("./assets/a\\"b.png")');
  assert.equal(
    formatReference("mdx", "./assets/a.png", "Preview"),
    '<img src="./assets/a.png" alt="Preview" />',
  );
  assert.equal(formatReference("markdown", "./assets/a.png", "A [shot]"), "![A \\[shot\\]](./assets/a.png)");
  assert.equal(formatReference("path", "./assets/a.png", "ignored"), "./assets/a.png");
})

test("describes edit kinds and alt-text support", () => {
  assert.equal(pasteTitle("html", false), "Paste image as HTML asset");
  assert.equal(pasteTitle("path", true), "Paste image as path asset with details");
  assert.equal(formatSupportsAltText("mdx"), true);
  assert.equal(formatSupportsAltText("css"), false);
})

test("recognizes supported MIME and file candidates", () => {
  assert.equal(isPotentialImage("IMAGE/PNG; charset=binary", "clipboard"), true);
  assert.equal(isPotentialImage("files", "photo.JPEG"), true);
  assert.equal(isPotentialImage("application/octet-stream", "photo.png"), true);
  assert.equal(isPotentialImage("files", "archive..PNG"), true);
  assert.equal(isPotentialImage("files", "vector.svg"), false);
  assert.equal(isPotentialImage("image/gif", "image.gif"), true);
  assert.equal(isPotentialImage("image/webp", "image.webp"), true);
})

test("accepts original GIF and WebP containers and rejects mismatched declarations", () => {
  const gif = Uint8Array.from(Buffer.from("R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw==", "base64"));
  const webp = Uint8Array.from(Buffer.from("UklGRiIAAABXRUJQVlA4IBYAAAAwAQCdASoBAAEADsD+JaQAA3AAAAAA", "base64"));
  // Use the container's actual length; media validation does not transcode it.
  new DataView(webp.buffer).setUint32(4, webp.length - 8, true);
  assert.deepEqual(validateImage(gif, "image/gif", "original.gif", 1024), { mime: "image/gif", extension: ".gif" });
  assert.deepEqual(validateImage(webp, "image/webp", "original.webp", 1024), { mime: "image/webp", extension: ".webp" });
  assert.throws(() => validateImage(gif, "image/png", "wrong.png", 1024), (error: unknown) => error instanceof MediaError && error.code === "mime-mismatch");
  assert.throws(() => validateImage(webp.subarray(0, 19), "image/webp", "broken.webp", 1024));
})

test("validates PNG bytes and normalizes the extension", () => {
  assert.deepEqual(validateImage(png, "image/png", "clipboard", 32), {
    extension: ".png",
    mime: "image/png",
  });
})

test("validates JPEG bytes and preserves a safe jpeg extension", () => {
  assert.deepEqual(validateImage(jpeg, "image/jpeg", "photo.jpeg", 32), {
    extension: ".jpeg",
    mime: "image/jpeg",
  });
  assert.deepEqual(validateImage(jpeg, "image/jpg", "photo.bin", 32), {
    extension: ".jpg",
    mime: "image/jpeg",
  });
})

test("detects media from a file entry without a declared MIME", () => {
  assert.deepEqual(validateImage(png, undefined, "capture.png", 32), {
    extension: ".png",
    mime: "image/png",
  });
})

test("rejects empty, oversized, unsupported, and mismatched data", () => {
  assert.throws(
    () => validateImage(new Uint8Array(), "image/png", "image.png", 32),
    (error: unknown) => error instanceof MediaError && error.code === "empty",
  );
  assert.throws(
    () => validateImage(png, "image/png", "image.png", 7),
    (error: unknown) => error instanceof MediaError && error.code === "too-large",
  );
  assert.throws(
    () => validateImage(Uint8Array.of(1, 2, 3, 4), "image/png", "image.png", 32),
    (error: unknown) => error instanceof MediaError && error.code === "unsupported",
  );
  assert.throws(
    () => validateImage(png, "image/jpeg", "image.jpg", 32),
    (error: unknown) => error instanceof MediaError && error.code === "mime-mismatch",
  );
  assert.throws(
    () => validateImage(png, "image/png", "image.jpeg", 32),
    (error: unknown) => error instanceof MediaError && error.code === "mime-mismatch",
  );
  assert.throws(
    () => validateImage(jpeg, undefined, "image.png", 32),
    (error: unknown) => error instanceof MediaError && error.code === "mime-mismatch",
  );
})

test("resolves document and workspace destination templates", () => {
  const input = {
    documentPath: "/project/docs/guide.html",
    workspacePath: "/project",
  };
  assert.equal(
    resolveDestinationPath({ ...input, template: "${documentDir}/assets" }),
    "/project/docs/assets",
  );
  assert.equal(
    resolveDestinationPath({ ...input, template: "${workspaceFolder}/media/${documentName}" }),
    "/project/media/guide",
  );
  assert.equal(
    resolveDestinationPath({ ...input, template: "images" }),
    "/project/docs/images",
  );
  assert.equal(
    resolveDestinationPath({
      documentPath: "/c:/Project/docs/guide.html",
      template: "${workspaceFolder}/media",
      workspacePath: "/C:/PROJECT",
    }),
    "/C:/PROJECT/media",
  );
})

test("keeps an outside-workspace document inside its own directory", () => {
  assert.equal(
    resolveDestinationPath({ documentPath: "/notes/page.html", template: "assets" }),
    "/notes/assets",
  );
})

test("rejects traversal, unsupported tokens, schemes, and reserved segments", () => {
  const input = { documentPath: "/project/docs/page.html", workspacePath: "/project" };
  for (const template of ["../outside", "/absolute", "${env}/assets", "file:assets", "${workspaceFolder}/NUL"]) {
    assert.throws(() => resolveDestinationPath({ ...input, template }), PathError);
  }
  assert.throws(
    () => resolveDestinationPath({ documentPath: "/notes/page.html", template: "${workspaceFolder}/assets" }),
    /needs a workspace folder/,
  );
})

test("creates encoded document-relative references", () => {
  assert.equal(
    createReferencePath(
      "/project/docs/page.html",
      "/project/docs/assets/Hero image (1).png",
      "documentRelative",
      "/project",
    ),
    "./assets/Hero%20image%20%281%29.png",
  );
  assert.equal(
    createReferencePath(
      "/project/docs/page.html",
      "/project/media/hero.png",
      "documentRelative",
      "/project",
    ),
    "../media/hero.png",
  );
})

test("creates workspace-relative references and rejects outside assets", () => {
  assert.equal(
    createReferencePath(
      "/project/docs/page.html",
      "/project/media/hero.png",
      "workspaceRelative",
      "/project",
    ),
    "/media/hero.png",
  );
  assert.throws(
    () => createReferencePath(
      "/project/docs/page.html",
      "/outside/hero.png",
      "workspaceRelative",
      "/project",
    ),
    PathError,
  );
})

test("handles root paths and relative path identity", () => {
  assert.equal(dirnameUriPath("/page.html"), "/");
  assert.equal(basenameUriPath("/project/docs/page.html"), "page.html");
  assert.equal(relativeUriPath("/project/docs", "/project/docs"), ".");
  assert.equal(relativeUriPath("/C:/project/docs", "/c:/project/media/image.png"), "../media/image.png");
  assert.equal(relativeUriPath("/C:/Project/Docs", "/c:/project/MEDIA/image.png"), "../MEDIA/image.png");
  assert.throws(() => relativeUriPath("/C:/project/docs", "/D:/media/image.png"), /different drives/);
})

